#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 long long numberOfWays(string s){long long ones=0,zeros=0;for(char c:s)(c=='1'?ones:zeros)++;
  long long l1=0,l0=0,ans=0;for(char c:s){if(c=='0'){--zeros;ans+=l1*ones;++l0;}else{--ones;ans+=l0*zeros;++l1;}}return ans;
 }
};
